// Worker entry: one origin for the API and the web (map #86, spike #90). The API paths go to
// the Hono application of apps/server; everything else is the Next.js application built by
// OpenNext (`opennextjs-cloudflare build` writes ./.open-next/worker.js before wrangler bundles
// this file).
import {
	apiFetch,
	isApiPath,
	type WorkerContext,
	type WorkerEnv,
} from "server/worker";

// @ts-expect-error generated by `opennextjs-cloudflare build`, absent from the source tree
import openNext from "./.open-next/worker.js";

// @ts-expect-error same generated file: Durable Object classes, when OpenNext configures any
export * from "./.open-next/worker.js";

export default {
	async fetch(
		request: Request,
		env: WorkerEnv,
		ctx: WorkerContext,
	): Promise<Response> {
		if (isApiPath(new URL(request.url).pathname)) {
			return apiFetch(request, env, ctx);
		}
		return openNext.fetch(request, env, ctx);
	},
};
